from AlgorithmImports import *
from datetime import datetime, timedelta, time as clock_time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_end = None
        self._bucket_minutes = {}

        self.held_symbol = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None
        self.equity_liquidation_pending = False

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()

        # Never intentionally carry an option into its expiration date.
        if self.held_symbol is not None and self.Time.date() >= self.held_symbol.ID.Date.date():
            self.no_entry_date = self.Time.date()
            self._submit_exit("expiration safeguard")

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_builder(spy_bar, data)

        self._check_time_stop()

        if self.held_symbol is not None and self.exit_order_id is None:
            self._check_profit_target(data)

    def _update_five_minute_builder(self, minute_bar: TradeBar, data: Slice):
        end = minute_bar.EndTime

        # Regular-session minute bars ending 09:31 through 16:00 form bars
        # ending 09:35, 09:40, ..., 16:00.
        if end.time() < clock_time(9, 31) or end.time() > clock_time(16, 0):
            return

        minutes_to_boundary = (5 - (end.minute % 5)) % 5
        bucket_end = end.replace(second=0, microsecond=0) + timedelta(minutes=minutes_to_boundary)

        if bucket_end.time() < clock_time(9, 35) or bucket_end.time() > clock_time(16, 0):
            return

        if self._bucket_end != bucket_end:
            self._bucket_end = bucket_end
            self._bucket_minutes = {}

        self._bucket_minutes[end] = minute_bar

        expected_ends = [bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)]
        if not all(t in self._bucket_minutes for t in expected_ends):
            if end == bucket_end:
                # Do not synthesize incomplete five-minute bars.
                self._bucket_end = None
                self._bucket_minutes = {}
            return

        close = self._bucket_minutes[bucket_end].Close
        self._bucket_end = None
        self._bucket_minutes = {}

        self._on_completed_five_minute_bar(bucket_end, close, data)

    def _on_completed_five_minute_bar(self, end_time, close, data: Slice):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value
        previous_slow = self.slow.Current.Value

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if end_time.time() < clock_time(9, 45) or end_time.time() > clock_time(14, 30):
            return

        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        self._try_enter(data)

    def _try_enter(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Entry skipped: no current SPY price.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain in current Slice.")
            return

        today = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiry = eligible_expirations[0]
        minimum_strike = spy_bar.Close * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def _check_profit_target(self, data: Slice):
        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self._submit_exit("50% profit target")

    def _check_time_stop(self):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        if self.Time.time() != clock_time(15, 45):
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() == self._previous_trading_day(expiry_date):
            self._submit_exit("15:45 pre-expiration time stop")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(datetime.combine(candidate, clock_time.min)):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            self.Transactions.CancelOrder(order.Id, f"Replacing exit: {reason}")

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self.equity_liquidation_pending = False
            return

        if not self.equity_liquidation_pending:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} @ {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug("Entry order canceled or invalid.")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}")
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_fill_price = None
                    self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
