from AlgorithmImports import *
from datetime import datetime, timedelta, time as clock_time


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.close_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_exit_order_id = None
        self.no_entry_date = None

        self.five_minute_consolidator = TradeBarConsolidator(
            self._five_minute_calendar
        )
        self.five_minute_consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy, self.five_minute_consolidator
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self._time_stop
        )

    def _five_minute_calendar(self, dt):
        # Algorithm and SPY exchange time are both New York time.
        start = dt.replace(
            minute=dt.minute - (dt.minute % 5),
            second=0,
            microsecond=0
        )
        return CalendarInfo(start, timedelta(minutes=5))

    def _on_five_minute_bar(self, sender, bar):
        # Capture the completed values before adding the new close.
        if self.close_window.Count >= 20:
            prior_fast = sum(
                self.close_window[i] for i in range(5)
            ) / 5.0
            prior_slow = sum(
                self.close_window[i] for i in range(20)
            ) / 20.0
        else:
            prior_fast = None
            prior_slow = None

        self.close_window.Add(float(bar.Close))

        if self.close_window.Count < 20:
            return

        current_fast = sum(
            self.close_window[i] for i in range(5)
        ) / 5.0
        current_slow = sum(
            self.close_window[i] for i in range(20)
        ) / 20.0

        is_bullish_cross = (
            prior_fast is not None
            and prior_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end_time = bar.EndTime
        if (
            is_bullish_cross
            and clock_time(9, 45) <= bar_end_time.time() <= clock_time(14, 30)
        ):
            # OnData receives the current Slice immediately after consolidation.
            self.pending_entry_bar_end = bar_end_time

    def OnData(self, data):
        self._handle_unexpected_spy_position()

        # If exercise/assignment created SPY holdings, flatten first and do
        # nothing else in this Slice.
        if self.Portfolio[self.spy].Quantity != 0:
            return

        self._expiration_safety_exit()

        self._check_profit_target(data)

        if self.pending_entry_bar_end is not None:
            signal_time = self.pending_entry_bar_end
            self.pending_entry_bar_end = None
            self._try_enter(data, signal_time)

    def _try_enter(self, data, signal_time):
        if self.no_entry_date == self.Time.date():
            return

        if self._has_option_position() or self._entry_order_is_open():
            return

        if self.option_canonical not in data.OptionChains:
            self.Debug(
                f"{signal_time}: skipped entry; no SPY option chain in Slice."
            )
            return

        chain = data.OptionChains[self.option_canonical]
        underlying_price = self.Securities[self.spy].Price
        if underlying_price <= 0:
            self.Debug(
                f"{signal_time}: skipped entry; SPY price unavailable."
            )
            return

        earliest_expiry = self.Time.date() + timedelta(days=7)
        valid_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= earliest_expiry
        })

        if not valid_expiries:
            self.Debug(
                f"{signal_time}: skipped entry; no call expiry at least 7 calendar days away."
            )
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{signal_time}: skipped entry; no qualifying call at {selected_expiry}."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute SMA crossover call entry"
        )
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"{signal_time}: submitted entry for {selected.Symbol}."
        )

    def _check_profit_target(self, data):
        if not self._has_option_position():
            return

        if self.exit_order_id is not None:
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if (
            self.entry_fill_price is not None
            and midpoint >= self.entry_fill_price * 1.50
        ):
            self._submit_option_exit("50% profit target")

    def _time_stop(self):
        if not self._has_option_position() or self.held_expiry is None:
            return

        if self.Time.date() == self._previous_spy_trading_day(self.held_expiry):
            self._submit_option_exit("15:45 pre-expiration time stop")

    def _expiration_safety_exit(self):
        if not self._has_option_position() or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.no_entry_date = self.Time.date()
            self._submit_option_exit("expiration safety exit")

    def _previous_spy_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, clock_time.min), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_option_exit(self, reason):
        if not self._has_option_position() or self.exit_order_id is not None:
            return

        for ticket in self.Transactions.GetOpenOrderTickets():
            if ticket.Symbol == self.held_contract:
                ticket.Cancel(f"Replacing open exit: {reason}")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted exit for {self.held_contract}; {reason}.")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_exit_order_id is not None:
            return

        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected option exercise/assignment cleanup"
        )
        self.equity_exit_order_id = ticket.OrderId
        self.no_entry_date = self.Time.date()
        self.Debug(
            f"{self.Time}: unexpected SPY exercise/assignment position; "
            f"submitted liquidation for {quantity} shares."
        )

    def _has_option_position(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def _entry_order_is_open(self):
        if self.entry_order_id is None:
            return False

