        self._evaluate_option_exit(data)

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        bar_end = bar.EndTime
        bar_start = bar_end - timedelta(minutes=1)

        regular_open = time(9, 30)
        regular_close = time(16, 0)

        if bar_start.time() < regular_open or bar_end.time() > regular_close:
            return

        minute_of_day = bar_end.hour * 60 + bar_end.minute
        bucket_minutes = ((minute_of_day + 4) // 5) * 5
        bucket_end = datetime.combine(
            bar_end.date(),
            time(bucket_minutes // 60, bucket_minutes % 60)
        )

        if self.five_minute_date != bar_end.date() or self.five_minute_end != bucket_end:
            self.five_minute_date = bar_end.date()
            self.five_minute_end = bucket_end
            self.five_minute_minutes = {}

        self.five_minute_minutes[bar_end] = bar

        # A five-minute bar ending at 09:35 contains minute bars ending
        # 09:31, 09:32, 09:33, 09:34, and 09:35.
        if bar_end != bucket_end:
            return

        expected_end_times = [
            bucket_end - timedelta(minutes=offset)
            for offset in range(4, -1, -1)
        ]

        if not all(expected_time in self.five_minute_minutes
                   for expected_time in expected_end_times):
            # Missing data is deliberately not synthesized or forward-filled.
            self.five_minute_minutes = {}
            return

        close = self.five_minute_minutes[bucket_end].Close
        self.five_minute_minutes = {}
        self._on_completed_five_minute_bar(bucket_end, close, data)

