            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Entry skipped: no eligible call at expiration {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId

        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {selected_expiry}, "
            f"strike {selected.Strike}."
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        expiry_date = self.held_contract.ID.Date.date()
        prior_trading_day = self._previous_spy_trading_day(expiry_date)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("15:45 expiration-eve time stop")
            return

        if self.entry_fill_price is None or self._order_is_open(self.exit_order_id):
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
