            self._submit_exit("15:45 pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        if not data.quote_bars.contains_key(self.held_contract):
            return

        quote = data.quote_bars[self.held_contract]
        if quote.bid is None or quote.ask is None:
            return

        bid = float(quote.bid.close)
        ask = float(quote.ask.close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit(
                f"50% profit target, midpoint {midpoint:.2f}, entry {self.entry_price:.2f}"
            )

    def _submit_exit(self, reason: str):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            self.transactions.cancel_order(order.id, "Replacing with market exit")

        ticket = self.market_order(self.held_contract, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"EXIT submitted {self.held_contract}: {reason}")

    def _handle_expiring_option_positions(self):
        expiring_positions = [
            security for security in self.securities.values
            if security.symbol.security_type == SecurityType.OPTION
            and security.holdings.invested
            and security.symbol.id.date.date() <= self.time.date()
        ]

        if not expiring_positions:
            return

        self.no_entry_date = self.time.date()

        for security in expiring_positions:
            if self.exit_order_id is None:
                self.held_contract = security.symbol
                self.held_expiry = security.symbol.id.date.date()
                self._submit_exit("expiration processing safeguard")

    def _handle_unexpected_spy_position(self):
        if self.portfolio[self.spy].invested and not self.spy_liquidation_pending:
            quantity = self.portfolio[self.spy].quantity
            self.market_order(self.spy, -quantity)
            self.spy_liquidation_pending = True
            self.debug(
                f"Unexpected SPY exercise/assignment position ({quantity}); liquidating"
            )

    def _has_option_holding(self) -> bool:
        return any(
            security.symbol.security_type == SecurityType.OPTION
            and security.holdings.invested
            for security in self.securities.values
        )

    def _is_time_stop_moment(self) -> bool:
        if self.held_expiry is None:
            return False

        previous_trading_day = self._previous_trading_day(self.held_expiry)
        return (
            self.time.date() == previous_trading_day
            and self.time.hour == 15
            and self.time.minute == 45
        )

    def _is_expiration_day_or_later(self) -> bool:
        return self.held_expiry is not None and self.time.date() >= self.held_expiry

    def _previous_trading_day(self, expiry_date):
        expiry_midnight = datetime.combine(expiry_date, time.min)
        market_open = self.securities[self.spy].exchange.hours.get_previous_market_open(
            expiry_midnight,
            False
        )
        return market_open.date()

    @staticmethod
    def _is_regular_session_minute(timestamp: datetime) -> bool:
        return time(9, 31) <= timestamp.time() <= time(16, 0)

    @staticmethod
    def _five_minute_period_end(timestamp: datetime) -> datetime:
        minutes_after_open = (
            timestamp.hour * 60 + timestamp.minute
            - (9 * 60 + 30)
        )
        ending_offset = ((minutes_after_open + 4) // 5) * 5
        return timestamp.replace(
            hour=9 + (30 + ending_offset) // 60,
            minute=(30 + ending_offset) % 60,
            second=0,
            microsecond=0
        )
