        if self.Time.date() >= expiry_date and self.Portfolio[self.held_symbol].Invested:
            self.no_entry_dates.add(self.Time.date())
            self._submit_option_exit("expiration processing safeguard")

    def _submit_option_exit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            order_ticket = self.Transactions.GetOrderTicket(order.Id)
            if order_ticket is not None:
                order_ticket.Cancel("Replacing open exit order")

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_symbol}")

    def _liquidate_unexpected_spy(self):
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted")

    def OnOrderEvent(self, order_event):
        terminal_statuses = {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        }

        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_symbol} at {self.entry_price}"
                )
            elif order_event.Status in terminal_statuses:
                self.entry_order_id = None

        elif order_event.OrderId == self.exit_order_id:
            if order_event.Status in terminal_statuses:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                    )

                self.exit_order_id = None
                if (
                    self.held_symbol is not None and
                    not self.Portfolio[self.held_symbol].Invested
                ):
                    self.held_symbol = None
                    self.entry_price = None

        elif order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in terminal_statuses:
                self.spy_liquidation_order_id = None

        self._liquidate_unexpected_spy()
