from AlgorithmImports import *
from collections import deque
from datetime import datetime, time as clock_time, timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption(self.spy, Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.entry_signal_pending = False

        self.held_option = None
        self.held_expiry_date = None
        self.entry_fill_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_date = None
        self.spy_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.RegisterConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, bar):
        # Actual consolidated bars only are used; missing intervals are never filled.
        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        crossed_up = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        eligible_time = clock_time(9, 45) <= bar_time <= clock_time(14, 30)

        if (
            crossed_up
            and eligible_time
            and not self._has_option_position()
            and not self._entry_order_is_open()
            and self.no_entry_date != bar.EndTime.date()
        ):
            # Consumed in the OnData call for this same minute Slice.
            self.entry_signal_pending = True

    def OnData(self, data):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety_exit()

        if self._has_option_position():
            self._handle_time_stop()
            self._handle_profit_target(data)

        if self.entry_signal_pending:
            self.entry_signal_pending = False

            if (
                not self._has_option_position()
                and not self._entry_order_is_open()
                and self.no_entry_date != self.Time.date()
            ):
                self._try_enter(data)

    def _try_enter(self, data):
        if not data.Bars.ContainsKey(self.spy):
            self.Debug("Skipped entry: SPY price was unavailable in the signal Slice.")
